import React, { useState, useEffect, useRef } from 'react';

function DisplaySettings({ dotSize, setDotSize, opacity, setOpacity, showLabels, setShowLabels, labelFontSize, setLabelFontSize }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    if (!open) return;
    const handler = (e) => {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  return (
    <div className="display-settings" ref={ref}>
      <button
        className={`display-settings__trigger${open ? ' display-settings__trigger--open' : ''}`}
        onClick={() => setOpen((v) => !v)}
        title="Display settings: point size, opacity, labels"
      >
        ⚙ Settings
      </button>
      {open && (
        <div className="display-settings__popover">
          <div className="display-settings__section">Display Settings</div>

          <label className="display-settings__row" title="Adjust the size of scatter plot points">
            <span className="display-settings__label">Point Size</span>
            <input
              className="toolbar__slider"
              type="range" min="1" max="10" step="1"
              value={dotSize}
              onChange={(e) => setDotSize(Number(e.target.value))}
            />
            <span className="display-settings__value">{dotSize}</span>
          </label>

          <label className="display-settings__row" title="Adjust the transparency of scatter plot points">
            <span className="display-settings__label">Opacity</span>
            <input
              className="toolbar__slider"
              type="range" min="0.1" max="1" step="0.05"
              value={opacity}
              onChange={(e) => setOpacity(Number(e.target.value))}
            />
            <span className="display-settings__value">{Math.round(opacity * 100)}%</span>
          </label>

          <label className="display-settings__row display-settings__row--checkbox" title="Toggle cluster label text on the plot">
            <span className="display-settings__label">Show Labels</span>
            <input
              type="checkbox"
              checked={showLabels}
              onChange={(e) => setShowLabels(e.target.checked)}
            />
          </label>

          <label className="display-settings__row" title="Adjust the font size of cluster labels">
            <span className="display-settings__label">Label Size</span>
            <input
              className="toolbar__slider"
              type="range" min="8" max="20" step="1"
              value={labelFontSize}
              onChange={(e) => setLabelFontSize(Number(e.target.value))}
            />
            <span className="display-settings__value">{labelFontSize}px</span>
          </label>
        </div>
      )}
    </div>
  );
}

export default DisplaySettings;
