import React from 'react';

/**
 * Tooltip — absolutely positioned, rendered as a portal-like overlay.
 * Props:
 *   visible: boolean
 *   x, y: number (page coordinates)
 *   text: string
 */
function Tooltip({ visible, x, y, text }) {
  if (!visible || !text) return null;

  const truncated =
    text.length > 150 ? text.slice(0, 147) + '…' : text;

  // Keep tooltip inside viewport by checking right edge
  const style = {
    left: x + 12,
    top: y - 10,
  };

  return (
    <div className="tooltip" style={style}>
      {truncated}
    </div>
  );
}

export default Tooltip;
