import React from 'react';

const DATASETS = [
  { value: 'vispub', label: 'VisPub — Visualization Papers' },
  { value: 'frankenstein', label: 'Frankenstein — Gothic Fiction' },
  { value: 'physics', label: 'Physics — Research Papers' },
];

function DatasetSelector({ currentDataset, onChange }) {
  return (
    <div className="dataset-selector">
      <label htmlFor="dataset-select" className="dataset-selector__label">
        Dataset
      </label>
      <select
        id="dataset-select"
        className="dataset-selector__select"
        value={currentDataset}
        onChange={(e) => onChange(e.target.value)}
        title="Switch the active text corpus. All selections and test points will reset"
      >
        {DATASETS.map((ds) => (
          <option key={ds.value} value={ds.value}>
            {ds.label}
          </option>
        ))}
      </select>
    </div>
  );
}

export default DatasetSelector;
