import React, { useState } from 'react';

function Legend({ semanticLabels, highlightedCluster, onHighlight }) {
  const [open, setOpen] = useState(true);
  const [search, setSearch] = useState('');

  if (!semanticLabels || semanticLabels.length === 0) return null;

  const PALETTE = [
    '#4e79a7', '#a0cbe8',
    '#f28e2b', '#ffbe7d',
    '#59a14f', '#8cd17d',
    '#b6992d', '#f1ce63',
    '#499894', '#86bcb6',
    '#e15759', '#ff9da7',
    '#79706e', '#bab0ac',
    '#d37295', '#fabfd2',
    '#b07aa1', '#d4a6c8',
    '#9d7660', '#d7b5a6',
  ];
  const color = (i) => PALETTE[i % PALETTE.length];

  const filtered = semanticLabels
    .map((label, i) => ({ label, index: i }))
    .filter(({ label }) => label.toLowerCase().includes(search.toLowerCase()));

  const handleClick = (index) => {
    if (highlightedCluster === index) onHighlight(null);
    else onHighlight(index);
  };

  return (
    <div className="legend legend--inline">
      <button
        className="legend__toggle"
        onClick={() => setOpen((v) => !v)}
        title="Show/hide cluster legend. Click a cluster to isolate it on the plot"
      >
        <span className="legend__toggle-label">Clusters</span>
        {highlightedCluster !== null && <span className="legend__active-dot" />}
        <span className="legend__chevron">{open ? '▾' : '▸'}</span>
      </button>
      {open && (
        <>
          <input
            type="text"
            placeholder="Filter clusters…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="legend__search"
          />
          <ul className="legend__list">
            {filtered.map(({ label, index }) => {
              const isHighlighted = highlightedCluster === index;
              const isDimmed = highlightedCluster !== null && !isHighlighted;
              return (
                <li
                  key={index}
                  className={`legend__item ${isHighlighted ? 'legend__item--highlighted' : ''} ${isDimmed ? 'legend__item--dimmed' : ''}`}
                  onClick={() => handleClick(index)}
                  title={`Click to isolate cluster: ${label}`}
                >
                  <span className="legend__swatch" style={{ backgroundColor: color(index) }} />
                  <span className="legend__label">{label}</span>
                </li>
              );
            })}
          </ul>
          {highlightedCluster !== null && (
            <button className="legend__clear-btn" onClick={() => onHighlight(null)} title="Remove cluster filter and show all points">
              Show all clusters
            </button>
          )}
        </>
      )}
    </div>
  );
}

export default Legend;
