import React, { useState } from 'react';

function formatTime(ts) {
  const diff = Date.now() - ts;
  if (diff < 60000) return 'just now';
  if (diff < 3600000) return `${Math.floor(diff / 60000)}m`;
  return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

function SelectionsHistoryPanel({ selections, activeSelectionId, onRestore, onDelete }) {
  const [expanded, setExpanded] = useState(false);
  const [expandedId, setExpandedId] = useState(null);

  return (
    <div className="history-panel">
      <button
        className="history-panel__header"
        onClick={() => setExpanded((v) => !v)}
        title="Past lasso selections with their explanations"
      >
        <span className="history-panel__title">History</span>
        <span className="history-panel__badge">{selections.length}</span>
        <span className={`history-panel__chevron${expanded ? ' history-panel__chevron--up' : ''}`}>▾</span>
      </button>

      {expanded && (
        <div className="history-panel__body">
          {selections.length === 0 ? (
            <p className="history-panel__empty">No selections yet</p>
          ) : (
            <ul className="history-panel__list">
              {selections.map((sel) => {
                const isActive = sel.id === activeSelectionId;
                const isExpanded = expandedId === sel.id;
                return (
                  <li key={sel.id} className={`history-chip${isActive ? ' history-chip--active' : ''}`}>
                    <div
                      className="history-chip__row"
                      onClick={() => setExpandedId(isExpanded ? null : sel.id)}
                    >
                      <span className="history-chip__badge">{sel.dataset}</span>
                      <span className="history-chip__time">{formatTime(sel.timestamp)}</span>
                      <span className="history-chip__preview">
                        {sel.explanation
                          ? sel.explanation.slice(0, 45) + (sel.explanation.length > 45 ? '…' : '')
                          : `${sel.indices.length} points`}
                      </span>
                      <span className="history-chip__expand">{isExpanded ? '▴' : '▾'}</span>
                    </div>
                    {isExpanded && (
                      <div className="history-chip__detail">
                        {sel.explanation && (
                          <p className="history-chip__explanation">{sel.explanation.slice(0, 200)}{sel.explanation.length > 200 ? '…' : ''}</p>
                        )}
                        <div className="history-chip__actions">
                          <button
                            className="btn btn--primary btn--sm"
                            onClick={() => onRestore(sel)}
                            title="Reload this selection and its explanation into the main view"
                          >
                            Restore
                          </button>
                          <button
                            className="btn btn--danger btn--sm"
                            onClick={() => onDelete(sel.id)}
                            title="Remove this entry from history"
                          >
                            Delete
                          </button>
                        </div>
                      </div>
                    )}
                  </li>
                );
              })}
            </ul>
          )}
        </div>
      )}
    </div>
  );
}

export default SelectionsHistoryPanel;
